import { UseQueryResult, useQuery } from '@tanstack/react-query'
import { useMemo } from 'react'
import { useEthersProvider } from 'hooks/useEthersProvider'
import { useAccountMeta } from 'uniswap/src/contexts/UniswapContext'
import { UseQueryApiHelperHookArgs } from 'uniswap/src/data/apiClients/types'
import { CreateLPPositionRequest, CreateLPPositionResponse } from 'uniswap/src/data/tradingApi/__generated__'
import { isAbstractChain, getAbstractContracts } from 'uniswap/src/constants/abstractContracts'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ReactQueryCacheKey } from 'utilities/src/reactQuery/cache'
import { ethers } from 'ethers'
import { Token, Price } from '@uniswap/sdk-core'
import { encodeSqrtRatioX96, TickMath } from '@uniswap/v3-sdk'

// V2 Router ABI - only the functions we need
const V2_ROUTER_ABI = [
  {
    name: 'addLiquidity',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: 'tokenA', type: 'address' },
      { name: 'tokenB', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: 'amountADesired', type: 'uint256' },
      { name: 'amountBDesired', type: 'uint256' },
      { name: 'amountAMin', type: 'uint256' },
      { name: 'amountBMin', type: 'uint256' },
      { name: 'to', type: 'address' },
      { name: 'deadline', type: 'uint256' }
    ],
    outputs: [
      { name: 'amountA', type: 'uint256' },
      { name: 'amountB', type: 'uint256' },
      { name: 'liquidity', type: 'uint256' }
    ]
  },
  {
    name: 'addLiquidityETH',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      { name: 'token', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: 'amountTokenDesired', type: 'uint256' },
      { name: 'amountTokenMin', type: 'uint256' },
      { name: 'amountETHMin', type: 'uint256' },
      { name: 'to', type: 'address' },
      { name: 'deadline', type: 'uint256' }
    ],
    outputs: [
      { name: 'amountToken', type: 'uint256' },
      { name: 'amountETH', type: 'uint256' },
      { name: 'liquidity', type: 'uint256' }
    ]
  },
  {
    name: 'poolFor',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'tokenA', type: 'address' },
      { name: 'tokenB', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: '_factory', type: 'address' }
    ],
    outputs: [
      { name: 'pool', type: 'address' }
    ]
  },
  {
    name: 'quoteAddLiquidity',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'tokenA', type: 'address' },
      { name: 'tokenB', type: 'address' },
      { name: 'stable', type: 'bool' },
      { name: '_factory', type: 'address' },
      { name: 'amountADesired', type: 'uint256' },
      { name: 'amountBDesired', type: 'uint256' }
    ],
    outputs: [
      { name: 'amountA', type: 'uint256' },
      { name: 'amountB', type: 'uint256' },
      { name: 'liquidity', type: 'uint256' }
    ]
  }
] as const

// Abstract DEX V3 NFT Position Manager ABI - uses tickSpacing instead of fee
const V3_NFT_MANAGER_ABI = [
  {
    name: 'mint',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      {
        name: 'params',
        type: 'tuple',
        components: [
          { name: 'token0', type: 'address' },
          { name: 'token1', type: 'address' },
          { name: 'tickSpacing', type: 'int24' },
          { name: 'tickLower', type: 'int24' },
          { name: 'tickUpper', type: 'int24' },
          { name: 'amount0Desired', type: 'uint256' },
          { name: 'amount1Desired', type: 'uint256' },
          { name: 'amount0Min', type: 'uint256' },
          { name: 'amount1Min', type: 'uint256' },
          { name: 'recipient', type: 'address' },
          { name: 'deadline', type: 'uint256' },
          { name: 'sqrtPriceX96', type: 'uint160' }
        ]
      }
    ],
    outputs: [
      { name: 'tokenId', type: 'uint256' },
      { name: 'liquidity', type: 'uint128' },
      { name: 'amount0', type: 'uint256' },
      { name: 'amount1', type: 'uint256' }
    ]
  },
  {
    name: 'createAndInitializePoolIfNecessary',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      { name: 'token0', type: 'address' },
      { name: 'token1', type: 'address' },
      { name: 'tickSpacing', type: 'int24' },
      { name: 'sqrtPriceX96', type: 'uint160' }
    ],
    outputs: [
      { name: 'pool', type: 'address' }
    ]
  },
  {
    name: 'multicall',
    type: 'function',
    stateMutability: 'payable',
    inputs: [
      { name: 'data', type: 'bytes[]' }
    ],
    outputs: [
      { name: 'results', type: 'bytes[]' }
    ]
  }
] as const

interface AbstractLpCreationParams {
  token0?: string
  token1?: string
  amount0?: string
  amount1?: string
  chainId: UniverseChainId
  slippageTolerance?: number
  protocolVersion?: 'V2' | 'V3'
  // V3-specific parameters
  fee?: number
  tickLower?: number
  tickUpper?: number
  sqrtPriceX96?: string
  createPool?: boolean
  tokenId?: string // For increase liquidity operations
}

export function useAbstractLpPositionCalldataQuery({
  params,
  deadlineInMinutes = 20,
  ...rest
}: UseQueryApiHelperHookArgs<CreateLPPositionRequest, CreateLPPositionResponse> & {
  deadlineInMinutes?: number
}): UseQueryResult<CreateLPPositionResponse> {
  const account = useAccountMeta()
  const address = account?.address

  // Extract Abstract-specific params from the request
  const abstractParams: AbstractLpCreationParams | null = useMemo(() => {
    if (!params) return null

    try {
      const chainId = params.chainId as UniverseChainId

      // Extract data from the actual structure
      const token0 = params.position?.pool?.token0
      const token1 = params.position?.pool?.token1

      // Detect protocol version based on position structure
      const fee = params.position?.pool?.fee
      const tickLower = params.position?.tickLower
      const tickUpper = params.position?.tickUpper
      const sqrtPriceX96 = params.initialPrice ? params.initialPrice : params.position?.pool?.sqrtRatioX96
      const createPool = params.createPool

      // Detect protocol version from explicit protocol field or position structure
      const protocolFromField = (params as any).protocol
      const protocolFromStructure = (fee !== undefined || tickLower !== undefined) ? 'V3' : 'V2'
      // If tokenId is present, this is a V3 increase liquidity operation
      const protocolFromTokenId = params.tokenId ? 'V3' : null
      const protocolVersion = protocolFromField || protocolFromTokenId || protocolFromStructure


      // Handle amounts based on independentToken
      let amount0, amount1
      const independentAmount = params.independentAmount
      const dependentAmount = params.defaultDependentAmount

      if (params.independentToken === 'TOKEN_0') {
        amount0 = independentAmount
        amount1 = dependentAmount
      } else if (params.independentToken === 'TOKEN_1') {
        amount0 = dependentAmount
        amount1 = independentAmount
      } else {
        // Fallback: assume TOKEN_0 is independent
        amount0 = independentAmount
        amount1 = dependentAmount
      }

      // If amounts are still missing, try direct properties
      if (!amount0 && params.amount0) amount0 = params.amount0
      if (!amount1 && params.amount1) amount1 = params.amount1

      const slippageTolerance = params.slippageTolerance || 0.5

      // Extract tokenId for increase liquidity operations
      const tokenId = params.tokenId

      return {
        chainId,
        token0,
        token1,
        amount0,
        amount1,
        slippageTolerance,
        protocolVersion,
        fee,
        tickLower,
        tickUpper,
        sqrtPriceX96,
        createPool,
        tokenId,
      }
    } catch (error) {
      return null
    }
  }, [params])

  const contracts = getAbstractContracts(abstractParams?.chainId || UniverseChainId.Sepolia)
  const routerAddress = contracts?.router
  const poolFactoryAddress = contracts?.poolFactory
  const nftManagerAddress = contracts?.nonfungiblePositionManager
  const clFactoryAddress = contracts?.clFactory
  const provider = useEthersProvider({ chainId: abstractParams?.chainId || UniverseChainId.Sepolia })

  const queryKey = [ReactQueryCacheKey.AbstractLpApproval, 'lp-creation', abstractParams, address]



  return useQuery<CreateLPPositionResponse>({
    queryKey,
    queryFn: async () => {
      if (!abstractParams || !address || !provider) {
        throw new Error('Invalid parameters for Abstract LP creation')
      }

      if (abstractParams.protocolVersion === 'V2' && (!routerAddress || !poolFactoryAddress)) {
        throw new Error('Invalid V2 router/factory for Abstract LP creation')
      }

      if (abstractParams.protocolVersion === 'V3' && (!nftManagerAddress || !clFactoryAddress)) {
        throw new Error('Invalid V3 NFT manager/factory for Abstract LP creation')
      }

      if (!isAbstractChain(abstractParams.chainId)) {
        throw new Error('LP creation only supported on Abstract chains')
      }

      const { token0, token1, slippageTolerance = 0.5 } = abstractParams
      let { amount0, amount1 } = abstractParams

      if (!token0 || !token1 || !amount0 || !amount1) {
        throw new Error('Missing required token or amount parameters')
      }

      // Calculate deadline (current time + minutes)
      const deadline = Math.floor(Date.now() / 1000) + (deadlineInMinutes * 60)

      // Calculate minimum amounts with slippage tolerance
      const slippageMultiplier = (100 - slippageTolerance) / 100
      let amountAMin = ethers.BigNumber.from(amount0).mul(Math.floor(slippageMultiplier * 100)).div(100).toString()
      let amountBMin = ethers.BigNumber.from(amount1).mul(Math.floor(slippageMultiplier * 100)).div(100).toString()

      // Handle V3 positions separately
      if (abstractParams.protocolVersion === 'V3') {
        // Check if this is increase liquidity (tokenId provided) or mint new position
        if (abstractParams.tokenId) {
          return await increaseV3Liquidity({
            abstractParams,
            address,
            nftManagerAddress: nftManagerAddress!,
            deadline,
            amount0,
            amount1,
            amountAMin,
            amountBMin,
            provider
          })
        } else {
          return await createV3Position({
            abstractParams,
            address,
            nftManagerAddress: nftManagerAddress!,
            clFactoryAddress: clFactoryAddress!,
            deadline,
            amount0,
            amount1,
            amountAMin,
            amountBMin,
            provider
          })
        }
      }

      // V2 Logic continues below...
      // Check if this involves native ETH (not WETH)
      // Native ETH is represented as 'ETH', 'NATIVE', or NATIVE_CHAIN_ID in the token addresses
      const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000'
      const isETHPair = token0 === 'NATIVE' || token0.toLowerCase() === 'eth' || token0.toLowerCase() === 'native' || token0.toLowerCase() === ZERO_ADDRESS.toLowerCase() ||
                       token1 === 'NATIVE' || token1.toLowerCase() === 'eth' || token1.toLowerCase() === 'native' || token1.toLowerCase() === ZERO_ADDRESS.toLowerCase()

      try {
        // For pool operations, convert native ETH to WETH address
        const WETH_ADDRESS = '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d' // Abstract testnet WETH
        const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000'
        const poolToken0 = (token0 === 'NATIVE' || token0.toLowerCase() === 'eth' || token0.toLowerCase() === 'native' || token0.toLowerCase() === ZERO_ADDRESS.toLowerCase()) ? WETH_ADDRESS : token0
        const poolToken1 = (token1 === 'NATIVE' || token1.toLowerCase() === 'eth' || token1.toLowerCase() === 'native' || token1.toLowerCase() === ZERO_ADDRESS.toLowerCase()) ? WETH_ADDRESS : token1

        // Skip pool validation for ETH pairs as it causes contract call issues
        // For ETH pairs, proceed directly to transaction generation
        if (!isETHPair) {
          try {
            // First check if the pool exists using the router's poolFor function
            const routerContract = new ethers.Contract(routerAddress, V2_ROUTER_ABI, provider)
            const poolAddress = await routerContract.poolFor(poolToken0, poolToken1, false, poolFactoryAddress)

            if (poolAddress !== ethers.constants.AddressZero) {
              // Check what the optimal amounts would be according to the contract
              try {
                const [optimalAmountA, optimalAmountB, optimalLiquidity] = await routerContract.quoteAddLiquidity(
                  poolToken0, poolToken1, false, poolFactoryAddress, amount0, amount1
                )

                // Use the contract's optimal amounts instead of our requested amounts
                const optimalAmount0 = optimalAmountA.toString()
                const optimalAmount1 = optimalAmountB.toString()

                // Recalculate minimums based on optimal amounts with same slippage
                const slippageMultiplier = (100 - slippageTolerance) / 100
                const optimalAmountAMin = ethers.BigNumber.from(optimalAmount0).mul(Math.floor(slippageMultiplier * 100)).div(100).toString()
                const optimalAmountBMin = ethers.BigNumber.from(optimalAmount1).mul(Math.floor(slippageMultiplier * 100)).div(100).toString()

                // Override the original amounts with optimal amounts
                amount0 = optimalAmount0
                amount1 = optimalAmount1
                amountAMin = optimalAmountAMin
                amountBMin = optimalAmountBMin
              } catch (quoteError) {
                // Continue with original amounts if quote fails
              }
            }
          } catch (poolCheckError) {
            // Continue with original amounts if pool check fails
          }
        }

        let calldata: string
        let value = '0'

        if (isETHPair) {
          // addLiquidityETH - handle native ETH pairs
          const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000'
          const isToken0ETH = token0 === 'NATIVE' || token0.toLowerCase() === 'eth' || token0.toLowerCase() === 'native' || token0.toLowerCase() === ZERO_ADDRESS.toLowerCase()
          const tokenAddress = isToken0ETH ? token1 : token0
          const tokenAmount = isToken0ETH ? amount1 : amount0
          const ethAmount = isToken0ETH ? amount0 : amount1
          const tokenMin = isToken0ETH ? amountBMin : amountAMin
          const ethMin = isToken0ETH ? amountAMin : amountBMin

          const routerInterface = new ethers.utils.Interface(V2_ROUTER_ABI)
          calldata = routerInterface.encodeFunctionData('addLiquidityETH', [
            tokenAddress,
            false, // stable = false for volatile pools
            tokenAmount,
            tokenMin,
            ethMin,
            address,
            deadline
          ])
          value = ethAmount
        } else {
          // addLiquidity


          const routerInterface = new ethers.utils.Interface(V2_ROUTER_ABI)
          calldata = routerInterface.encodeFunctionData('addLiquidity', [
            poolToken0,
            poolToken1,
            false, // stable = false for volatile pools
            amount0,
            amount1,
            amountAMin,
            amountBMin,
            address,
            deadline
          ])
        }

        const response: CreateLPPositionResponse = {
          create: {
            to: routerAddress,
            data: calldata,
            value,
            from: address,
            chainId: abstractParams.chainId,
          },
          gasFee: '100000000000000', // 100k gas * 1 gwei = 0.0001 ETH
          dependentAmount: undefined, // We'll calculate this if needed
        }

        // Try to simulate the transaction to get better error details
        try {
          await provider.estimateGas({
            to: routerAddress,
            data: calldata,
            value,
            from: address
          })

        } catch (gasError) {
          // Continue anyway - let the UI handle the gas estimation
        }


        return response
      } catch (error) {
        throw error
      }
    },
    ...rest,
  })
}

// Helper function to create V3 positions
async function createV3Position({
  abstractParams,
  address,
  nftManagerAddress,
  clFactoryAddress,
  deadline,
  amount0,
  amount1,
  amountAMin,
  amountBMin,
  provider
}: {
  abstractParams: AbstractLpCreationParams
  address: string
  nftManagerAddress: string
  clFactoryAddress: string
  deadline: number
  amount0: string
  amount1: string
  amountAMin: string
  amountBMin: string
  provider: any
}): Promise<CreateLPPositionResponse> {
  let { token0, token1, fee, tickLower, tickUpper, sqrtPriceX96, createPool } = abstractParams

  if (!fee || tickLower === undefined || tickUpper === undefined) {
    throw new Error('Missing V3 parameters: fee, tickLower, tickUpper')
  }

  // CRITICAL: Ensure token0 < token1 (Uniswap V3 requirement)
  let finalToken0 = token0
  let finalToken1 = token1
  let finalAmount0 = amount0
  let finalAmount1 = amount1
  let finalAmount0Min = amountAMin
  let finalAmount1Min = amountBMin

  if (token0 && token1 && token0.toLowerCase() > token1.toLowerCase()) {
    // Swap token order and amounts
    finalToken0 = token1
    finalToken1 = token0
    finalAmount0 = amount1
    finalAmount1 = amount0
    finalAmount0Min = amountBMin
    finalAmount1Min = amountAMin
  }

  // CRITICAL: Convert native ETH to WETH for V3 pools (Uniswap V3 only works with ERC-20 tokens)
  const WETH_ADDRESS = '0x9edcde0257f2386ce177c3a7fcdd97787f0d841d' // Abstract testnet WETH

  // Track which tokens were originally ETH before conversion
  const isToken0OriginallyETH = finalToken0 === 'NATIVE' || finalToken0?.toLowerCase() === 'eth' || finalToken0?.toLowerCase() === 'native' || finalToken0?.toLowerCase() === '0x0000000000000000000000000000000000000000'
  const isToken1OriginallyETH = finalToken1 === 'NATIVE' || finalToken1?.toLowerCase() === 'eth' || finalToken1?.toLowerCase() === 'native' || finalToken1?.toLowerCase() === '0x0000000000000000000000000000000000000000'

  // Convert zero address, 'ETH', or 'NATIVE' to WETH address
  if (isToken0OriginallyETH) {
    finalToken0 = WETH_ADDRESS
  }
  if (isToken1OriginallyETH) {
    finalToken1 = WETH_ADDRESS
  }

  // For Abstract DEX, we need to use tick spacing instead of fee amount
  // Convert fee to tick spacing for Abstract DEX
  const TICK_SPACINGS: { [key: number]: number } = {
    100: 1,     // 0.01% -> tick spacing 1
    500: 100,   // 0.05% -> tick spacing 100
    3000: 200,  // 0.3% -> tick spacing 200
    10000: 2000 // 1% -> tick spacing 2000
  }

  const tickSpacing = TICK_SPACINGS[fee] || 200

  // Check if pool exists for this token pair and tick spacing
  let poolExists = false
  let finalSqrtPriceX96 = '0' // Default for existing pools

  try {
    const clFactory = new ethers.Contract(clFactoryAddress, [
      'function getPool(address tokenA, address tokenB, int24 tickSpacing) view returns (address pool)'
    ], provider)

    const poolAddress = await clFactory.getPool(finalToken0, finalToken1, tickSpacing)
    poolExists = poolAddress !== '0x0000000000000000000000000000000000000000'

    if (!poolExists) {
      // New pool - calculate sqrtPriceX96 from token amounts ratio
      if (sqrtPriceX96) {
        // Use provided sqrtPriceX96 if available
        finalSqrtPriceX96 = sqrtPriceX96
        console.log('Using provided sqrtPriceX96 for new pool:', finalSqrtPriceX96)
      } else if (finalAmount0 && finalAmount1) {
        // Calculate sqrtPriceX96 from the ratio of amounts
        try {
          // Create token objects (assume 18 decimals for Abstract testnet tokens)
          const token0Obj = new Token(abstractParams.chainId, finalToken0, 18)
          const token1Obj = new Token(abstractParams.chainId, finalToken1, 18)

          // Create price from amounts ratio
          const price = new Price(token0Obj, token1Obj, finalAmount0, finalAmount1)

          // Convert to sqrtPriceX96
          const calculatedSqrtPriceX96 = encodeSqrtRatioX96(price.numerator, price.denominator)
          finalSqrtPriceX96 = calculatedSqrtPriceX96.toString()

          console.log('Calculated sqrtPriceX96 for new pool:', {
            price: price.toSignificant(6),
            sqrtPriceX96: finalSqrtPriceX96,
            amounts: { finalAmount0, finalAmount1 }
          })
        } catch (error) {
          console.error('Failed to calculate sqrtPriceX96:', error)
          throw new Error('Cannot create new pool without valid price calculation')
        }
      } else {
        throw new Error('New pool requires either sqrtPriceX96 or valid token amounts to calculate initial price')
      }
    }
    // If pool exists, keep finalSqrtPriceX96 as '0'

    console.log('Pool existence check:', {
      poolAddress,
      poolExists,
      finalSqrtPriceX96,
      tokens: { finalToken0, finalToken1 },
      tickSpacing
    })

  } catch (error) {
    console.warn('Failed to check pool existence:', error)
    // Default to existing pool behavior
    poolExists = true
  }

  // Fix tick alignment for Abstract DEX - round to nearest valid tick
  const alignedTickLower = Math.floor(tickLower / tickSpacing) * tickSpacing
  const alignedTickUpper = Math.ceil(tickUpper / tickSpacing) * tickSpacing

  // Ensure tick range is valid
  if (alignedTickLower >= alignedTickUpper) {
    // If alignment made them equal or inverted, ensure minimum range
    const finalTickLower = alignedTickLower
    const finalTickUpper = alignedTickLower + tickSpacing
    console.log('Adjusted tick range:', { original: { tickLower, tickUpper }, aligned: { finalTickLower, finalTickUpper }, tickSpacing })
    tickLower = finalTickLower
    tickUpper = finalTickUpper
  } else {
    tickLower = alignedTickLower
    tickUpper = alignedTickUpper
  }


  const calls: string[] = []

  // 1. Create pool if necessary (using tick spacing for Abstract DEX)
  if (createPool && sqrtPriceX96) {
    const createPoolCalldata = new ethers.utils.Interface(V3_NFT_MANAGER_ABI).encodeFunctionData(
      'createAndInitializePoolIfNecessary',
      [finalToken0, finalToken1, tickSpacing, sqrtPriceX96] // Abstract DEX uses tickSpacing in all function calls
    )
    calls.push(createPoolCalldata)
  }

  // 2. Mint position
  const mintParams = {
    token0: finalToken0,
    token1: finalToken1,
    tickSpacing, // Abstract DEX uses tickSpacing instead of fee in function calls
    tickLower,
    tickUpper,
    amount0Desired: finalAmount0,
    amount1Desired: finalAmount1,
    amount0Min: finalAmount0Min,
    amount1Min: finalAmount1Min,
    recipient: address,
    deadline,
    sqrtPriceX96: finalSqrtPriceX96 // 0 for existing pools, calculated value for new pools
  }

  const mintCalldata = new ethers.utils.Interface(V3_NFT_MANAGER_ABI).encodeFunctionData('mint', [mintParams])
  calls.push(mintCalldata)

  // 3. Create multicall if we have multiple operations
  let finalCalldata: string
  let value = '0'

  if (calls.length === 1) {
    finalCalldata = calls[0]
  } else {
    finalCalldata = new ethers.utils.Interface(V3_NFT_MANAGER_ABI).encodeFunctionData('multicall', [calls])
  }

  // Handle native ETH positions - send ETH value when original tokens were ETH
  // The Position Manager will wrap the ETH to WETH automatically
  if (isToken0OriginallyETH || isToken1OriginallyETH) {
    const ethAmount = isToken0OriginallyETH ? finalAmount0 : finalAmount1
    value = ethAmount
  }


  // Try to estimate gas
  let gasEstimate = '300000' // Default fallback
  try {
    const gas = await provider.estimateGas({
      to: nftManagerAddress,
      data: finalCalldata,
      value,
      from: address
    })
    gasEstimate = gas.toString()
  } catch (gasError) {
    // Use fallback gas estimate
  }

  const response: CreateLPPositionResponse = {
    create: {
      to: nftManagerAddress,
      data: finalCalldata,
      value,
      from: address,
      chainId: abstractParams.chainId,
    },
    gasFeeCreate: ethers.BigNumber.from(gasEstimate).mul('1000000000').toString(), // gas * 1 gwei
  }

  return response
}

// Helper function to increase liquidity on existing V3 positions
async function increaseV3Liquidity({
  abstractParams,
  address,
  nftManagerAddress,
  deadline,
  amount0,
  amount1,
  amountAMin,
  amountBMin,
  provider
}: {
  abstractParams: AbstractLpCreationParams
  address: string
  nftManagerAddress: string
  deadline: number
  amount0: string
  amount1: string
  amountAMin: string
  amountBMin: string
  provider: any
}): Promise<CreateLPPositionResponse> {
  const { tokenId } = abstractParams

  if (!tokenId) {
    throw new Error('Missing tokenId for increase liquidity operation')
  }

  // Build increase liquidity parameters
  const increaseParams = {
    tokenId: tokenId.toString(),
    amount0Desired: amount0,
    amount1Desired: amount1,
    amount0Min: amountAMin,
    amount1Min: amountBMin,
    deadline
  }

  // Add increaseLiquidity ABI if not already present
  const INCREASE_LIQUIDITY_ABI = [
    {
      name: 'increaseLiquidity',
      type: 'function',
      stateMutability: 'payable',
      inputs: [
        {
          name: 'params',
          type: 'tuple',
          components: [
            { name: 'tokenId', type: 'uint256' },
            { name: 'amount0Desired', type: 'uint256' },
            { name: 'amount1Desired', type: 'uint256' },
            { name: 'amount0Min', type: 'uint256' },
            { name: 'amount1Min', type: 'uint256' },
            { name: 'deadline', type: 'uint256' }
          ]
        }
      ],
      outputs: [
        { name: 'liquidity', type: 'uint128' },
        { name: 'amount0', type: 'uint256' },
        { name: 'amount1', type: 'uint256' }
      ]
    }
  ]

  // Encode the increaseLiquidity function call
  const increaseCalldata = new ethers.utils.Interface(INCREASE_LIQUIDITY_ABI).encodeFunctionData('increaseLiquidity', [increaseParams])

  // Handle ETH value for native ETH positions
  let value = '0'
  const { token0, token1 } = abstractParams

  // Check if either token is native ETH and set appropriate value
  const isToken0ETH = token0 === 'NATIVE' || token0?.toLowerCase() === 'eth' || token0?.toLowerCase() === 'native' || token0?.toLowerCase() === '0x0000000000000000000000000000000000000000'
  const isToken1ETH = token1 === 'NATIVE' || token1?.toLowerCase() === 'eth' || token1?.toLowerCase() === 'native' || token1?.toLowerCase() === '0x0000000000000000000000000000000000000000'

  if (isToken0ETH || isToken1ETH) {
    // Send ETH value for the appropriate token amount
    const ethAmount = isToken0ETH ? amount0 : amount1
    value = ethAmount
  }

  // Estimate gas for the transaction
  const gasEstimate = 300000 // Conservative estimate for increase liquidity

  const response: CreateLPPositionResponse = {
    create: {
      to: nftManagerAddress, // NFT Position Manager, not router
      data: increaseCalldata,
      value, // Send ETH if dealing with native ETH position
      from: address,
      chainId: abstractParams.chainId || 11124
    },
    gasFeeCreate: ethers.BigNumber.from(gasEstimate).mul('1000000000').toString(), // gas * 1 gwei
  }

  return response
}
